const cfg = $('Config').first().json;
const out = [];
for (const c of cfg.greenhouse_boards) out.push({ ats: 'greenhouse', company: c, url: 'https://boards-api.greenhouse.io/v1/boards/' + c + '/jobs?content=true' });
for (const c of cfg.lever_companies) out.push({ ats: 'lever', company: c, url: 'https://api.lever.co/v0/postings/' + c + '?mode=json' });
for (const c of cfg.ashby_boards) out.push({ ats: 'ashby', company: c, url: 'https://api.ashbyhq.com/posting-api/job-board/' + c });
return out.map(json => ({ json }));

// Normalise Greenhouse / Lever / Ashby responses and filter by title, location, freshness.
const cfg = $('Config').first().json;
const boards = $('Build board URLs').all();
const lc = s => String(s || '').toLowerCase();
const strip = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/&[a-z]+;/g, ' ');
const jobs = [];
for (const it of $input.all()) {
  const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const src = (boards[(pi && pi.item) || 0] || {}).json || {};
  const j = it.json;
  if (j.error) continue;
  if (src.ats === 'greenhouse') for (const x of j.jobs || []) jobs.push({ company: src.company, title: x.title, location: (x.location || {}).name, url: x.absolute_url, date: x.updated_at, text: strip(x.content) });
  else if (src.ats === 'ashby') for (const x of j.jobs || []) jobs.push({ company: src.company, title: x.title, location: (x.location || '') + (x.isRemote ? ' Remote' : ''), url: x.jobUrl, date: x.publishedAt, text: x.descriptionPlain });
  else if (src.ats === 'lever' && j.text) jobs.push({ company: src.company, title: j.text, location: ((j.categories || {}).location || '') + ' ' + (j.workplaceType || ''), url: j.hostedUrl, date: j.createdAt ? new Date(j.createdAt).toISOString() : '', text: j.descriptionPlain });
}
const titles = cfg.title_keywords.map(lc), locs = cfg.locations.map(lc), visa = cfg.sponsorship_terms.map(lc), excl = cfg.exclude_keywords.map(lc);
const minDate = Date.now() - Number(cfg.max_age_days) * 86400000;
return jobs.filter(x => titles.some(k => lc(x.title).includes(k)) && !excl.some(k => lc(x.title).includes(k))
    && locs.some(k => lc(x.location).includes(k)) && (!x.date || Date.parse(x.date) >= minDate))
  .map(x => ({ json: { ...x, sponsorship_mentioned: visa.some(k => lc(x.text).includes(k)), text: undefined } }));

const items = $input.all().map(i => i.json).sort((a, b) => Number(b.sponsorship_mentioned) - Number(a.sponsorship_mentioned));
if (!items.length) return [];
const text = items.length + ' new matching role(s)

' + items.map(x => (x.sponsorship_mentioned ? '[visa] ' : '') + x.company + ' | ' + x.title + ' | ' + x.location + '
' + x.url).join('

');
return [{ json: { text: text.slice(0, 4000) } }];
